        if self.top is None:
            self.top = Node(x)
        else:
            temp = self.top
            self.top = Node(x)
            self.top.next = temp

    def pop(self):
        if self.top.next is not None:
            temp = self.top.next
            self.top = self.top.next.next
            return temp
        self.top = None

    def size(self):
        return self._size

