        if not self.is_empty():
            return self.items[-1]

    def split(self):
        if self.top is None:
            return None
        result = DoubleEndedPila()
        result.top = self.top.next
        result.items = list(reversed(self.items[:-1]))

    def __contains__(self, x):
        if self.is_empty():
            return False
        sub, node, index = self, self._find(x), self.size() - 1
        while index > 0:
            if sub is node:
